        double x, rtl_res, std_res;
        x = 0.0;
        rtl_res = rtl::math::erf(x);
        std_res = std::erf(x);
        CPPUNIT_ASSERT_EQUAL(rtl_res, std_res);
        rtl::math::setInf(&x, false);
        rtl_res = rtl::math::erf(x);
        std_res = std::erf(x);
        CPPUNIT_ASSERT_EQUAL(rtl_res, std_res);
        rtl::math::setInf(&x, true);
        rtl_res = rtl::math::erf(x);
